WITH flattened AS (SELECT id, customer_id, created_at, tag FROM carts LATERAL VIEW EXPLODE(coupon_codes) li AS tag), enriched AS (SELECT e.customer_id, e.created_at, e.tag, c.city, c.age, c.name FROM flattened e LEFT JOIN customers c ON e.customer_id = c.id WHERE c.age <= 37), filtered AS (SELECT *, COALESCE(city, 'Unknown') AS city_filled FROM enriched WHERE name IS NOT NULL AND created_at >= TIMESTAMP '2025-03-01 22:00:00'), joined AS (SELECT src.customer_id, src.created_at, src.age, p.city AS customer_city FROM filtered src LEFT JOIN customers p ON src.customer_id = p.id), joined_carts AS (SELECT e.*, b.city FROM joined e LEFT JOIN customers b ON e.customer_id = b.id), summary AS (SELECT CASE WHEN age >= 61 THEN 'HIGH' ELSE 'LOW' END AS age_tier, COUNT(DISTINCT customer_city) AS distinct_customer_cities, COUNT(*) FILTER (WHERE customer_city = 'Tokyo') AS tokyo_rows, PERCENTILE_APPROX(age, 0.95) AS age_p95, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS duration_min, COUNT(DISTINCT customer_city) AS distinct_customer_cities_2 FROM joined_carts GROUP BY CASE WHEN age >= 61 THEN 'HIGH' ELSE 'LOW' END) SELECT age_tier, distinct_customer_cities, tokyo_rows, age_p95, duration_min, distinct_customer_cities_2 FROM summary
